#include "workload.h"
#ifdef __clang__
#define ANALYZE __attribute__((annotate("ape.analyze")))
#define INLINE __attribute__((annotate("ape.inline")))
#else
#define ANALYZE
#define INLINE
#endif
volatile uint8_t data_legacy[256] __attribute__((aligned(32), section(".chaser_data.00")));
INLINE static uint32_t kernel_legacy(void) {
    uint32_t sum = 0;
    for (int i = 0; i < 256; i += 32)
        sum += data_legacy[i];
    return sum;
}
/** @brief Execute one fixed job without resetting data or cache.
 * @return Load-count checksum, modulo 2^32. */
ANALYZE uint32_t task_job_legacy(void) {
    uint32_t sum = 0;
    for (int s = 0; s < 2; ++s)
        sum += kernel_legacy();
    return sum;
}
void workload_prepare(void) {
    for (int i = 0; i < 256; ++i) data_legacy[i] = 1;
}
uint32_t (*const workload_jobs[])(void) = {
    task_job_legacy,
};
const uint32_t workload_expected[] = {
16U
};

